struct Body {
    double x, y, z;
    double vx, vy, vz;
    double mass;
};

static inline void offset_momentum(Body bodies[], int nbodies) {
    double px = 0.0, py = 0.0, pz = 0.0;
    for (int i = 0; i < nbodies; ++i) {
        px += bodies[i].vx * bodies[i].mass;
        py += bodies[i].vy * bodies[i].mass;
        pz += bodies[i].vz * bodies[i].mass;
    }
    bodies[0].vx = -px / 4.0e-6;
    bodies[0].vy = -py / 4.0e-6;
    bodies[0].vz = -pz / 4.0e-6;
}

static inline double energy(const Body bodies[], int nbodies) {
    double e = 0.0;
    for (int i = 0; i < nbodies; ++i) {
        const Body& bi = bodies[i];
        e += 0.5 * bi.mass * (bi.vx * bi.vx + bi.vy * bi.vy + bi.vz * bi.vz);
        for (int j = i + 1; j < nbodies; ++j) {
            const Body& bj = bodies[j];
            double dx = bi.x - bj.x;
            double dy = bi.y - bj.y;
            double dz = bi.z - bj.z;
            double dist = std::sqrt(dx * dx + dy * dy + dz * dz);
            e -= (bi.mass * bj.mass) / dist;
        }
    }
    return e;
}

static inline void advance(Body bodies[], int nbodies, double dt) {
    for (int i = 0; i < nbodies; ++i) {
        for (int j = i + 1; j < nbodies; ++j) {
            double dx = bodies[i].x - bodies[j].x;
            double dy = bodies[i].y - bodies[j].y;
            double dz = bodies[i].z - bodies[j].z;
            double d2 = dx * dx + dy * dy + dz * dz;
            double dist = std::sqrt(d2);
            double mag = dt / (d2 * dist);

            bodies[i].vx -= dx * bodies[j].mass * mag;
            bodies[i].vy -= dy * bodies[j].mass * mag;
            bodies[i].vz -= dz * bodies[j].mass * mag;

            bodies[j].vx += dx * bodies[i].mass * mag;
            bodies[j].vy += dy * bodies[i].mass * mag;
            bodies[j].vz += dz * bodies[i].mass * mag;
        }
    }

    for (int i = 0; i < nbodies; ++i) {
        bodies[i].x += dt * bodies[i].vx;
        bodies[i].y += dt * bodies[i].vy;
        bodies[i].z += dt * bodies[i].vz;
    }
}

